import{JUNCTION as R}from'./junction-registration.mjs';
export function createJunctionOverlay({patch,canvasFactory}){if(patch?.width!==R.width||patch?.height!==R.height||typeof canvasFactory!=='function')throw Error('JUNCTION_INPUT');const owned=[];let disposed=false;const close=()=>{if(disposed)return;disposed=true;for(const c of owned){c.width=0;c.height=0}};try{const[x,y,x1,y1]=R.roiHalfOpen,w=x1-x,h=y1-y,t=canvasFactory(w,h);owned.push(t);const g=t.getContext('2d');g.drawImage(patch,R.referenceWorldRect[0]-x,R.referenceWorldRect[1]-y,R.referenceWorldRect[2],R.referenceWorldRect[3]);const pixels=g.getImageData(0,0,w,h);for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++){const a=Math.min(1,Math.min(xx+1,yy+1,w-xx,h-yy)/R.interiorFeather);pixels.data[(yy*w+xx)*4+3]=Math.round(pixels.data[(yy*w+xx)*4+3]*a)}g.putImageData(pixels,0,0);const f=canvasFactory(w,h);owned.push(f);const fg=f.getContext('2d');fg.save();try{fg.beginPath();R.foregroundPolygon.forEach(([px,py],i)=>i?fg.lineTo(px-x,py-y):fg.moveTo(px-x,py-y));fg.closePath();fg.clip();fg.drawImage(t,0,0)}finally{fg.restore()}return Object.freeze({registration:R,draw(ctx,{offsetX=0,offsetY=0}={}){if(!disposed)ctx.drawImage(t,x-offsetX,y-offsetY)},drawForeground(ctx,{offsetX=0,offsetY=0,actorFoot}={}){if(!disposed&&Array.isArray(actorFoot)&&actorFoot[1]<R.foregroundDepthY)ctx.drawImage(f,x-offsetX,y-offsetY)},dispose:close})}catch(e){close();throw e}}
